export function displayPlaceLabel(lang:string,point?:{label?:string}|null){
 const label=point?.label||'';
 const dictionary=(placeLabels as Record<string,Record<string,string>>)[lang];
 return dictionary&&Object.prototype.hasOwnProperty.call(dictionary,label)?dictionary[label]:label;
}

