 const startGps=async(b:Booking)=>{
  if(liveRef.current?.start_allowed===false){setMessage(t('liveNotAllowed'));return;}
  const requestApi=apiRef.current,token=requestApi.token,generation=++liveGeneration.current;
  const current=()=>generation===liveGeneration.current&&requestApi===apiRef.current&&requestApi.token===token&&stateRef.current==='live'&&appStateRef.current==='active'&&selectedBookingRef.current?.id===b.id;
  const permission=await Location.requestForegroundPermissionsAsync();
  if(!current())return;
  if(!permission.granted){setMessage(t('liveLocationPermissionDenied'));return;}
  const started=await requestApi.action('start_sharing',{booking_id:b.id});
  if(!started.sharing_id)throw new Error(t('liveNetworkError'));
  if(!current()){try{await requestApi.action('stop_sharing',{booking_id:b.id,sharing_id:started.sharing_id});}catch{}return;}
  gpsRef.current.id=started.sharing_id;gpsRef.current.booking=b.id;lastGpsSent.current=0;gpsUploadInFlight.current=false;gpsArrivalSent.current=false;setGpsId(started.sharing_id);
  const send=async(loc:Location.LocationObject)=>{
   if(!current()||gpsRef.current.id!==started.sharing_id)return;
   if(loc.coords.accuracy==null||loc.coords.accuracy>200){await stopGps(true);if(current())setMessage(t('livePoorAccuracy'));return;}
   const point=liveRef.current?.dropoff,drop=point&&Number.isFinite(point.lat)&&Number.isFinite(point.lon)?[point.lon,point.lat]:null;
   let arrived=false;
   if(drop){const dLat=(loc.coords.latitude-drop[1])*Math.PI/180,dLon=(loc.coords.longitude-drop[0])*Math.PI/180;const a=Math.sin(dLat/2)**2+Math.cos(drop[1]*Math.PI/180)*Math.cos(loc.coords.latitude*Math.PI/180)*Math.sin(dLon/2)**2;arrived=6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))<=150+loc.coords.accuracy;}
   if(arrived&&gpsArrivalSent.current)return;
   if(!arrived&&Date.now()-lastGpsSent.current<5000)return;
   if(gpsUploadInFlight.current&&!arrived)return;
   if(arrived){gpsArrivalSent.current=true;if(gpsRef.current.watch){gpsRef.current.watch.remove();gpsRef.current.watch=null;setGpsWatch(null);}}
   lastGpsSent.current=Date.now();gpsUploadInFlight.current=true;
   try{
    const result=await requestApi.action('share_location',{booking_id:b.id,sharing_id:started.sharing_id,lat:loc.coords.latitude,lon:loc.coords.longitude,accuracy:loc.coords.accuracy});
    if(current()&&gpsRef.current.id===started.sharing_id&&(result.sharing_allowed===false||result.stopped_reason==='arrival'))await stopGps(false);
   }catch(e){if(current()&&gpsRef.current.id===started.sharing_id){await stopGps(true);err(e);}}
   finally{gpsUploadInFlight.current=false;}
  };
  try{
   const initial=await Location.getCurrentPositionAsync({accuracy:Location.Accuracy.High});if(!current())return;await send(initial);if(!current()||gpsRef.current.id!==started.sharing_id)return;
   const watch=await Location.watchPositionAsync({accuracy:Location.Accuracy.High,timeInterval:5000,distanceInterval:0},loc=>void send(loc));
   if(!current()||gpsRef.current.id!==started.sharing_id){watch.remove();return;}gpsRef.current.watch=watch;setGpsWatch(watch);
  }catch(e){if(current()&&gpsRef.current.id===started.sharing_id)await stopGps(true);throw e;}
 };
